import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"What the gate is","description":"","frontmatter":{},"headers":[],"relativePath":"gate/index.md","filePath":"gate/index.md"}`),a={name:`gate/index.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="what-the-gate-is" tabindex="-1">What the gate is <a class="header-anchor" href="#what-the-gate-is" aria-label="Permalink to “What the gate is”">​</a></h1><p>The gate bootstraps guard rails for vibe coders. One guided run sets up Biome, knip, dependency-cruiser, and Vibator, and a shared package carries the configurations your project extends.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @vibator/gate</span></span></code></pre></div><p>Two packages, released together:</p><table tabindex="0"><thead><tr><th>Package</th><th>What it is</th></tr></thead><tbody><tr><td><code>@vibator/gate</code></td><td>The shared configurations projects extend</td></tr><tr><td><code>@vibator/create-gate</code></td><td>The wizard that sets a repository up</td></tr></tbody></table><h2 id="how-the-wizard-works" tabindex="-1">How the wizard works <a class="header-anchor" href="#how-the-wizard-works" aria-label="Permalink to “How the wizard works”">​</a></h2><p>The wizard walks numbered steps, one per tool. Each step shows what the tool is for, the exact changes as a diff, and the warnings. Say yes and the step is applied. Follow-ups such as <code>biome migrate</code> or replacing a taken npm script run only if you say yes to them too. Re-running is safe: it asks again and fixes only what is missing.</p><h2 id="how-it-stays-current" tabindex="-1">How it stays current <a class="header-anchor" href="#how-it-stays-current" aria-label="Permalink to “How it stays current”">​</a></h2><p>The wizard holds no configuration content. It writes thin configs that extend <code>@vibator/gate</code> and installs each tool as a devDependency. To update the standards across every gated project, bump <code>@vibator/gate</code>.</p><h2 id="the-presets" tabindex="-1">The presets <a class="header-anchor" href="#the-presets" aria-label="Permalink to “The presets”">​</a></h2><p>Each preset is one <code>extends</code> line in a thin local config:</p><table tabindex="0"><thead><tr><th>Preset</th><th>Enforces</th></tr></thead><tbody><tr><td><code>@vibator/gate/biome</code></td><td>Strict format and lint: complexity at most 8, functions at most 25 lines, files at most 400 lines</td></tr><tr><td><code>@vibator/gate/depcruise</code></td><td>No cycles, no test imports in production code, no undeclared or dev dependencies in production code</td></tr><tr><td><code>@vibator/gate/vibator</code></td><td>TSDoc on every declaration, meaningful names, array methods over single-statement loops, no deprecated APIs</td></tr><tr><td><code>@vibator/gate/tsconfig</code></td><td>Strictness flags only; module, target, and paths stay yours</td></tr></tbody></table><p>knip has no extends mechanism and runs with its defaults. commitlint extends <code>@commitlint/config-conventional</code> directly.</p><p>The <a href="/gate/standards.html">standards</a> page explains each standard, the failure it prevents, and how to adjust one for your project without weakening it for all.</p><h2 id="what-it-never-does" tabindex="-1">What it never does <a class="header-anchor" href="#what-it-never-does" aria-label="Permalink to “What it never does”">​</a></h2><ul><li>Overwrite or delete an existing configuration. Existing configs get an <code>extends</code> entry, existing hooks get the missing lines, everything else stays yours.</li><li>Impose an orchestrator. It suggests a <code>verify</code> npm script; how you chain the tools is your call.</li><li>Hang without a terminal. Every prompt has a flag, so scripts can run it end to end.</li></ul><h2 id="without-a-terminal" tabindex="-1">Without a terminal <a class="header-anchor" href="#without-a-terminal" aria-label="Permalink to “Without a terminal”">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @vibator/gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --defaults</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">              # accept the recommendations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @vibator/gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --defaults</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # JSON plan, no changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @vibator/gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lint=extend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --knip=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --depcruise=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --vibator=create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tsconfig=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hooks=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --commitlint=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --ci=skip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agents=yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --migrations=yes</span></span></code></pre></div><p>Without a terminal and without enough flags it exits with code 2 and prints the way out. It never hangs. After an interactive session it prints the flags-only command that repeats the same choices. <code>--help</code> lists every flag.</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};